@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + Birthday : date
}

abstract class AppUser {}

class BusinessOwner {
  + LinkedInAccount : string
}

class HungryCustomer {
  + DeliveryAddress : string
}

class Entertainer {
  + StageName : string
  + Bio : string
  + PricePer30Min : float
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : float
}

class Order {
  + OrderID : int
  + OrderDateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder {
  + EntertainmentType : string
  + Duration : int
}

enum Day {
  Monday
  Tuesday
  Wednesday
  Thursday
  Friday
  Saturday
  Sunday
}

User --|> AppUser
AppUser --|> BusinessOwner
AppUser --|> HungryCustomer
AppUser --|> Entertainer

BusinessOwner "1" -- "1..*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "1..*" Pizza : offers
HungryCustomer "1" -- "0..*" Order : places
Order "1" -- "1..*" Pizza : contains
Order "1" -- "0..1" EntertainmentOrder : is_type
EntertainmentOrder "*" -- "1" Entertainer : fulfilled_by
Entertainer "0..*" -- "0..*" PizzaRestaurant : works_at
PizzaRestaurant "1" -- "0..*" Day : availability

@enduml

